const fmt = (n, digits = 4) => Number.isFinite(n) ? Number(n.toFixed(digits)).toLocaleString("en-US", { maximumFractionDigits: digits }) : "Invalid result";
const finite = (...values) => values.every(v => v !== "" && Number.isFinite(Number(v)));
const dayUTC = value => { const [y,m,d] = value.split("-").map(Number); return Date.UTC(y,m-1,d); };
const dateAtUTC = ms => new Date(ms).toISOString().slice(0,10);
const gcd = (a,b) => { a=Math.abs(Math.trunc(a)); b=Math.abs(Math.trunc(b)); while(b){ const t=b;b=a%b;a=t; } return a; };
const secureInt = max => {
  if (!globalThis.crypto?.getRandomValues) throw Error("Secure random numbers are unavailable in this browser.");
  if (!Number.isSafeInteger(max) || max < 1 || max > 4294967296) throw Error("Invalid random range.");
  const limit = Math.floor(4294967296 / max) * max;
  const values = new Uint32Array(1);
  do { globalThis.crypto.getRandomValues(values); } while (values[0] >= limit);
  return values[0] % max;
};
